#define MAXN 505
#define MAXM 505
#define INF 1000000000

int N, M, Q;
char S[MAXN], T[MAXM];
int dist[MAXN][MAXM];
int qr[MAXN*MAXM], qc[MAXN*MAXM];

void bfs(int sr, int sc) {
    for(int i=0;i<N;i++) for(int j=0;j<M;j++) dist[i][j]=-1;
    int head=0, tail=0;
    dist[sr][sc]=0;
    qr[tail]=sr; qc[tail]=sc; tail++;
    while(head<tail){
        int r=qr[head], c=qc[head]; head++;
        int d=dist[r][c];
        // horizontal movement
        if(S[r]=='E' && c+1<M && dist[r][c+1]==-1){dist[r][c+1]=d+1;qr[tail]=r;qc[tail]=c+1;tail++;}
        if(S[r]=='W' && c-1>=0 && dist[r][c-1]==-1){dist[r][c-1]=d+1;qr[tail]=r;qc[tail]=c-1;tail++;}
        // vertical movement
        if(T[c]=='S' && r+1<N && dist[r+1][c]==-1){dist[r+1][c]=d+1;qr[tail]=r+1;qc[tail]=c;tail++;}
        if(T[c]=='N' && r-1>=0 && dist[r-1][c]==-1){dist[r-1][c]=d+1;qr[tail]=r;qc[tail]=c;tail++;}  // bug: should be r-1,c
    }
}

int main(){
    scanf("%d %d %d", &N, &M, &Q);
    scanf("%s %s", S, T);
    for(int q=0;q<Q;q++){
        int r1,c1,r2,c2;
        scanf("%d %d %d %d",&r1,&c1,&r2,&c2);
        r1--;c1--;r2--;c2--;
        bfs(r1,c1);
        printf("%d\n",dist[r2][c2]);
    }
}

#include <stdio.h>
