typedef long long ll;

static int lower_bound_int(int *a, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (a[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

static int upper_bound_int(int *a, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (a[m] <= x) l = m + 1;
        else r = m;
    }
    return l;
}

static ll minll(ll a, ll b) { return a < b ? a : b; }
static ll absll(ll x) { return x < 0 ? -x : x; }

int main(void) {
    int N, M, Q;
    if (scanf("%d %d %d", &N, &M, &Q) != 3) return 0;

    char *S = (char *)malloc((N + 5) * sizeof(char));
    char *T = (char *)malloc((M + 5) * sizeof(char));
    scanf("%s", S);
    scanf("%s", T);

    int *ER = (int *)malloc(N * sizeof(int)); // rows going east
    int *WR = (int *)malloc(N * sizeof(int)); // rows going west
    int *NC = (int *)malloc(M * sizeof(int)); // cols going north
    int *SC = (int *)malloc(M * sizeof(int)); // cols going south

    int eCnt = 0, wCnt = 0, nCnt = 0, sCnt = 0;
    for (int i = 0; i < N; i++) {
        if (S[i] == 'E') ER[eCnt++] = i + 1;
        else WR[wCnt++] = i + 1;
    }
    for (int j = 0; j < M; j++) {
        if (T[j] == 'N') NC[nCnt++] = j + 1;
        else SC[sCnt++] = j + 1;
    }

    while (Q--) {
        int a, b, c, d;
        scanf("%d %d %d %d", &a, &b, &c, &d);

        if (a == c && b == d) {
            printf("0\n");
            continue;
        }

        ll ans = (ll)4e18;

        // 1) horizontal then vertical
        // Need row a to allow movement from b to d, then column d to allow movement from a to c
        int ok1 = 0;
        if (b < d && S[a - 1] == 'E') ok1 = 1;
        if (b > d && S[a - 1] == 'W') ok1 = 1;
        if (b == d) ok1 = 1;

        if (ok1) {
            int okv = 0;
            if (a < c && T[d - 1] == 'N') okv = 1;
            if (a > c && T[d - 1] == 'S') okv = 1;
            if (a == c) okv = 1;
            if (okv) {
                ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
            }
        }

        // 2) vertical then horizontal
        // Need column b to allow movement from a to c, then row c to allow movement from b to d
        int ok2 = 0;
        if (a < c && T[b - 1] == 'N') ok2 = 1;
        if (a > c && T[b - 1] == 'S') ok2 = 1;
        if (a == c) ok2 = 1;

        if (ok2) {
            int okh = 0;
            if (b < d && S[c - 1] == 'E') okh = 1;
            if (b > d && S[c - 1] == 'W') okh = 1;
            if (b == d) okh = 1;
            if (okh) {
                ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
            }
        }

        // 3) one extra turn:
        // (a,b) -> (a,y) -> (c,y) -> (c,d)
        // Need:
        // row a supports b->y
        // col y supports a->c
        // row c supports y->d
        if (a != c) {
            int needVNorth = (a < c);
            int needHE1 = 0, needHW1 = 0;
            int needHE2 = 0, needHW2 = 0;

            if (b < d) {
                // y in [b,d]: first east, second west/east depending
                needHE1 = 1; // if y>b
                needHW2 = 1; // if y<d for move y->d east actually row c needs E when y<d
                needHW2 = 0;
            }

            // Instead of casework by intervals, enumerate 4 sign combinations:
            // row a dir fixed if b!=y
            // row c dir fixed if y!=d
            // col y dir fixed by a,c

            // Candidate y from intersections of required sets, nearest useful points among boundaries.
            int *V = needVNorth ? NC : SC;
            int vCnt = needVNorth ? nCnt : sCnt;

            // Case A: y >= b and y <= d  => row a needs E if y>b, row c needs E if y<d
            if (b <= d && S[a - 1] == 'E' && S[c - 1] == 'E') {
                int l = lower_bound_int(V, vCnt, b);
                if (l < vCnt && V[l] <= d) {
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                }
            }
            // Case B: y <= b and y <= d => row a needs W if y<b, row c needs E if y<d
            if (d <= b && S[a - 1] == 'W' && S[c - 1] == 'E') {
                int l = lower_bound_int(V, vCnt, d);
                if (l < vCnt && V[l] <= b) {
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                }
            }
            // Case C: y >= b and y >= d => row a needs E if y>b, row c needs W if y>d
            if (b <= d && S[a - 1] == 'E' && S[c - 1] == 'W') {
                int l = lower_bound_int(V, vCnt, d);
                if (l < vCnt) {
                    ll y = V[l];
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - y) + absll((ll)d - y));
                }
            }
            if (d < b && S[a - 1] == 'E' && S[c - 1] == 'W') {
                int l = lower_bound_int(V, vCnt, b);
                if (l < vCnt) {
                    ll y = V[l];
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - y) + absll((ll)d - y));
                }
            }
            // Case D: y <= b and y <= d => row a needs W, row c needs E already handled zero-extra if interval exists
            // Case E: y <= b and y >= d => row a needs W, row c needs W
            if (d <= b && S[a - 1] == 'W' && S[c - 1] == 'W') {
                int r = upper_bound_int(V, vCnt, d) - 1;
                if (r >= 0 && V[r] <= b && V[r] >= d) {
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                } else {
                    r = upper_bound_int(V, vCnt, b) - 1;
                    if (r >= 0) {
                        ll y = V[r];
                        ans = minll(ans, absll((ll)a - c) + absll((ll)b - y) + absll((ll)d - y));
                    }
                }
            }
            // Case F: y <= b and y >= d => row a W, row c W, covered above for d<=b
            // Case G: y <= min(b,d) with row a W, row c E
            if (S[a - 1] == 'W' && S[c - 1] == 'E') {
                int r = upper_bound_int(V, vCnt, (b < d ? b : d)) - 1;
                if (r >= 0) {
                    ll y = V[r];
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - y) + absll((ll)d - y));
                }
            }
            // Case H: y >= max(b,d) with row a E, row c W
            if (S[a - 1] == 'E' && S[c - 1] == 'W') {
                int l = lower_bound_int(V, vCnt, (b > d ? b : d));
                if (l < vCnt) {
                    ll y = V[l];
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - y) + absll((ll)d - y));
                }
            }
            // Case I: y in [min,max] with opposite row directions can give Manhattan
            if (b <= d && S[a - 1] == 'W' && S[c - 1] == 'E') {
                int l = lower_bound_int(V, vCnt, b);
                if (l < vCnt && V[l] <= d) {
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                }
            }
            if (d <= b && S[a - 1] == 'E' && S[c - 1] == 'W') {
                int l = lower_bound_int(V, vCnt, d);
                if (l < vCnt && V[l] <= b) {
                    ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                }
            }
        }

        // 4) symmetric one extra turn:
        // (a,b) -> (x,b) -> (x,d) -> (c,d)
        if (b != d) {
            int needHEast = (b < d);
            int *H = needHEast ? ER : WR;
            int hCnt = needHEast ? eCnt : wCnt;

            // Similar row-selection by x
            // Need column b supports a->x, row x supports b->d, column d supports x->c

            // x in interval [a,c] can give Manhattan when vertical directions fit
            if (a <= c) {
                if (T[b - 1] == 'N' && T[d - 1] == 'S') {
                    int l = lower_bound_int(H, hCnt, a);
                    if (l < hCnt && H[l] <= c) {
                        ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'N' && T[d - 1] == 'N') {
                    int l = lower_bound_int(H, hCnt, c);
                    if (l < hCnt) {
                        ll x = H[l];
                        ans = minll(ans, absll((ll)a - x) + absll((ll)c - x) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'S' && T[d - 1] == 'S') {
                    int r = upper_bound_int(H, hCnt, a) - 1;
                    if (r >= 0) {
                        ll x = H[r];
                        ans = minll(ans, absll((ll)a - x) + absll((ll)c - x) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'S' && T[d - 1] == 'N') {
                    int l = lower_bound_int(H, hCnt, a);
                    if (l < hCnt && H[l] <= c) {
                        ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                    }
                }
            } else {
                if (T[b - 1] == 'S' && T[d - 1] == 'N') {
                    int l = lower_bound_int(H, hCnt, c);
                    if (l < hCnt && H[l] <= a) {
                        ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'S' && T[d - 1] == 'S') {
                    int r = upper_bound_int(H, hCnt, c) - 1;
                    if (r >= 0) {
                        ll x = H[r];
                        ans = minll(ans, absll((ll)a - x) + absll((ll)c - x) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'N' && T[d - 1] == 'N') {
                    int l = lower_bound_int(H, hCnt, a);
                    if (l < hCnt) {
                        ll x = H[l];
                        ans = minll(ans, absll((ll)a - x) + absll((ll)c - x) + absll((ll)b - d));
                    }
                }
                if (T[b - 1] == 'N' && T[d - 1] == 'S') {
                    int l = lower_bound_int(H, hCnt, c);
                    if (l < hCnt && H[l] <= a) {
                        ans = minll(ans, absll((ll)a - c) + absll((ll)b - d));
                    }
                }
            }
        }

        if (ans > (ll)3e18) printf("-1\n");
        else printf("%lld\n", ans);
    }

    free(S);
    free(T);
    free(ER);
    free(WR);
