        // Move first vertically then horizontally
        if (T[x1] == 'S' && y1 <= south[x1]) {
            int ym = N - 1;
            if (S[ym] == 'E' && x1 <= east[ym]) {
                if (x2 >= x1) {
                    int dist = (ym - y1) + (x2 - x1);
                    if (y2 <= ym) dist += (ym - y2);
                    else continue;
                    ans = min(ans, dist);
                }
            }
            if (S[ym] == 'W' && x1 >= west[ym]) {
                if (x2 <= x1) {
                    int dist = (ym - y1) + (x1 - x2);
                    if (y2 <= ym) dist += (ym - y2);
                    else continue;
                    ans = min(ans, dist);
                }
            }
        }

        if (T[x1] == 'N' && y1 >= north[x1]) {
            int ym = 0;
            if (S[ym] == 'E' && x1 <= east[ym]) {
                if (x2 >= x1) {
                    int dist = (y1 - ym) + (x2 - x1);
                    if (y2 >= ym) dist += (y2 - ym);
                    else continue;
                    ans = min(ans, dist);
                }
            }
            if (S[ym] == 'W' && x1 >= west[ym]) {
                if (x2 <= x1) {
                    int dist = (y1 - ym) + (x1 - x2);
                    if (y2 >= ym) dist += (y2 - ym);
                    else continue;
                    ans = min(ans, dist);
                }
            }
        }

        if (ans == INF) cout << -1 << "\n";
