using ll = long long;
const ll INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;
    string S, T;
    cin >> S >> T;

    // Rows: 1..N
    // If S[i-1] == 'E', row i allows increasing column.
    // If S[i-1] == 'W', row i allows decreasing column.
    //
    // Columns: 1..M
    // If T[j-1] == 'N', column j allows increasing row.
    // If T[j-1] == 'S', column j allows decreasing row.
    //
    // Query: (a,b) -> (c,d), minimum directed Manhattan-like path length.

    // Prefix counts for quick existence checks.
    vector<int> prefE(N + 1, 0), prefW(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        prefE[i] = prefE[i - 1] + (S[i - 1] == 'E');
        prefW[i] = prefW[i - 1] + (S[i - 1] == 'W');
    }
    vector<int> prefN(M + 1, 0), prefS(M + 1, 0);
    for (int j = 1; j <= M; j++) {
        prefN[j] = prefN[j - 1] + (T[j - 1] == 'N');
        prefS[j] = prefS[j - 1] + (T[j - 1] == 'S');
    }

    auto hasRowDir = [&](int l, int r, char dir) -> bool {
        if (l > r) return false;
        if (dir == 'E') return prefE[r] - prefE[l - 1] > 0;
        return prefW[r] - prefW[l - 1] > 0;
    };
    auto hasColDir = [&](int l, int r, char dir) -> bool {
        if (l > r) return false;
        if (dir == 'N') return prefN[r] - prefN[l - 1] > 0;
        return prefS[r] - prefS[l - 1] > 0;
    };

    while (Q--) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;

        ll ans = INF;

        int dr = c - a;
        int dc = d - b;

        char needRow = (dc >= 0 ? 'E' : 'W');
        char needCol = (dr >= 0 ? 'N' : 'S');

        ll direct = llabs((ll)dr) + llabs((ll)dc);

        // Path type 1:
        // Move horizontally on row a, then vertically on column d.
        bool ok1 = true;
        if (dc != 0) {
            if ((dc > 0 && S[a - 1] != 'E') || (dc < 0 && S[a - 1] != 'W')) ok1 = false;
        }
        if (dr != 0) {
            if ((dr > 0 && T[d - 1] != 'N') || (dr < 0 && T[d - 1] != 'S')) ok1 = false;
        }
        if (ok1) ans = min(ans, direct);

        // Path type 2:
        // Move vertically on column b, then horizontally on row c.
        bool ok2 = true;
        if (dr != 0) {
            if ((dr > 0 && T[b - 1] != 'N') || (dr < 0 && T[b - 1] != 'S')) ok2 = false;
        }
        if (dc != 0) {
            if ((dc > 0 && S[c - 1] != 'E') || (dc < 0 && S[c - 1] != 'W')) ok2 = false;
        }
        if (ok2) ans = min(ans, direct);

        // If direct monotone path not possible, shortest path with one "detour"
        // is obtained by first moving to some usable row/column, then moving,
        // with extra cost 2 * distance to that row/column.
        //
        // Horizontal first via some row r where row r has needed horizontal direction,
        // and column b/a? Actually to change row before horizontal movement, we need:
        // from (a,b) move vertically to row r along column b using needCol,
        // then move horizontally from b to d on row r using needRow,
        // then vertically from r to c along column d using needCol.
        // This requires:
        // - T[b] has needCol
        // - T[d] has needCol
        // - some row r between a and c (inclusive, in movement direction) with needRow
        // Cost = |a-r| + |d-b| + |c-r| = direct + 2*dist(r, [a,c])
        // minimized by nearest such r to segment [min(a,c), max(a,c)], i.e. inside segment => direct.
        // If none inside, nearest outside gives extra 2*distance.
        //
        // Symmetric for vertical via some column x.

        // Candidate via a row with needed horizontal direction,
        // provided both endpoint columns allow needed vertical direction.
        bool colsOK = true;
        if (dr != 0) {
            if ((dr > 0 && T[b - 1] != 'N') || (dr < 0 && T[b - 1] != 'S')) colsOK = false;
            if ((dr > 0 && T[d - 1] != 'N') || (dr < 0 && T[d - 1] != 'S')) colsOK = false;
        }
        if (colsOK) {
            int L = min(a, c), R = max(a, c);
            if (hasRowDir(L, R, needRow)) {
                ans = min(ans, direct);
            } else {
                ll extra = INF;
                // nearest above/below segment
                if (needRow == 'E') {
                    // find nearest row with E outside [L,R]
                    // below
                    int cntBelow = prefE[L - 1];
                    if (cntBelow > 0) {
                        int lo = 1, hi = L - 1, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefE[L - 1] - prefE[mid - 1] > 0) {
                                pos = mid;
                                lo = mid + 1;
                            } else hi = mid - 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (L - pos));
                    }
                    // above
                    if (prefE[N] - prefE[R] > 0) {
                        int lo = R + 1, hi = N, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefE[mid] - prefE[R] > 0) {
                                pos = mid;
                                hi = mid - 1;
                            } else lo = mid + 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (pos - R));
                    }
                } else {
                    int cntBelow = prefW[L - 1];
                    if (cntBelow > 0) {
                        int lo = 1, hi = L - 1, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefW[L - 1] - prefW[mid - 1] > 0) {
                                pos = mid;
                                lo = mid + 1;
                            } else hi = mid - 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (L - pos));
                    }
                    if (prefW[N] - prefW[R] > 0) {
                        int lo = R + 1, hi = N, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefW[mid] - prefW[R] > 0) {
                                pos = mid;
                                hi = mid - 1;
                            } else lo = mid + 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (pos - R));
                    }
                }
                if (extra < INF) ans = min(ans, direct + extra);
            }
        }

        // Candidate via a column with needed vertical direction,
        // provided both endpoint rows allow needed horizontal direction.
        bool rowsOK = true;
        if (dc != 0) {
            if ((dc > 0 && S[a - 1] != 'E') || (dc < 0 && S[a - 1] != 'W')) rowsOK = false;
            if ((dc > 0 && S[c - 1] != 'E') || (dc < 0 && S[c - 1] != 'W')) rowsOK = false;
        }
        if (rowsOK) {
            int L = min(b, d), R = max(b, d);
            if (hasColDir(L, R, needCol)) {
                ans = min(ans, direct);
            } else {
                ll extra = INF;
                if (needCol == 'N') {
                    int cntLeft = prefN[L - 1];
                    if (cntLeft > 0) {
                        int lo = 1, hi = L - 1, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefN[L - 1] - prefN[mid - 1] > 0) {
                                pos = mid;
                                lo = mid + 1;
                            } else hi = mid - 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (L - pos));
                    }
                    if (prefN[M] - prefN[R] > 0) {
                        int lo = R + 1, hi = M, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefN[mid] - prefN[R] > 0) {
                                pos = mid;
                                hi = mid - 1;
                            } else lo = mid + 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (pos - R));
                    }
                } else {
                    int cntLeft = prefS[L - 1];
                    if (cntLeft > 0) {
                        int lo = 1, hi = L - 1, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefS[L - 1] - prefS[mid - 1] > 0) {
                                pos = mid;
                                lo = mid + 1;
                            } else hi = mid - 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (L - pos));
                    }
                    if (prefS[M] - prefS[R] > 0) {
                        int lo = R + 1, hi = M, pos = -1;
                        while (lo <= hi) {
                            int mid = (lo + hi) / 2;
                            if (prefS[mid] - prefS[R] > 0) {
                                pos = mid;
                                hi = mid - 1;
                            } else lo = mid + 1;
                        }
                        if (pos != -1) extra = min(extra, 2LL * (pos - R));
                    }
                }
                if (extra < INF) ans = min(ans, direct + extra);
            }
        }

        if (ans >= INF) ans = -1;
        cout << ans << '\n';
    }

    return 0;
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int N = Integer.parseInt(firstLine[0]);
        int M = Integer.parseInt(firstLine[1]);
        String S = br.readLine();
        String T = br.readLine();
        int Q = Integer.parseInt(br.readLine());

        // prefix sums: prefS[i] = number of 'E' in S[0..i-1]
        int[] prefS = new int[N + 1];
        for (int i = 0; i < N; i++) {
            prefS[i + 1] = prefS[i] + (S.charAt(i) == 'E' ? 1 : 0);
        }
        int[] prefT = new int[M + 1];
        for (int i = 0; i < M; i++) {
            prefT[i + 1] = prefT[i] + (T.charAt(i) == 'N' ? 1 : 0);
        }

        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            String[] parts = br.readLine().split(" ");
            int a = Integer.parseInt(parts[0]) - 1;
            int b = Integer.parseInt(parts[1]) - 1;
            int c = Integer.parseInt(parts[2]) - 1;
            int d = Integer.parseInt(parts[3]) - 1;

            // Check east-first path
            boolean eastFirst = false;
            if (b <= d) {
                int eastCount = prefS[a + 1] - prefS[a];
                if (eastCount == 1) { // S[a]=='E'
                    int eastSeg = prefS[a + 1] - prefS[a]; // actually just check S[a] == 'E'
                    if (S.charAt(a) == 'E') {
                        // all east moves from b to d in row a: only need S[a]=='E' always
                        // then north from a to c in column d: need T[d]=='N' for each step
                        int northSeg = prefT[d + 1] - prefT[Math.min(a, c) + 1]; // careful
                        // simpler: check if all T positions from min(a,c) to max(a,c)-1 are 'N'
                        int lo = Math.min(a, c);
                        int hi = Math.max(a, c);
                        int northCount = prefT[hi] - prefT[lo];
                        int needed = hi - lo;
                        if (northCount == needed && S.charAt(a) == 'E') {
                            eastFirst = true;
                        }
                    }
                }
            } else {
                // cannot go east if b > d because only east direction allowed
            }

            // Check north-first path
            boolean northFirst = false;
            if (a <= c) {
                if (T.charAt(b) == 'N') {
                    int lo = Math.min(b, d);
                    int hi = Math.max(b, d);
                    int eastCount = prefS[c + 1] - prefS[Math.min(a, c)]; // wait, row c is fixed after moving north
                    // Actually after north moves, we are at row c, then go east from b to d
                    int eastSeg = prefS[c + 1] - prefS[c]; // row c
                    if (S.charAt(c) == 'E') {
                        int eastNeeded = hi - lo;
                        int eastHave = prefS[c + 1] - prefS[c]; // just check if S[c]=='E' for all
                        // But to go east from b to d, all steps are in row c, so need S[c]=='E'
                        // and then north part: from a to c in column b: need T[b]=='N' for each
                        int northLo = Math.min(a, c);
                        int northHi = Math.max(a, c);
                        int northCount = prefT[northHi] - prefT[northLo];
                        int northNeeded = northHi - northLo;
                        if (northCount == northNeeded && S.charAt(c) == 'E') {
                            northFirst = true;
                        }
                    }
                }
            }

            int dist = -1;
            if (eastFirst) {
                dist = (d - b) + (c - a);
            } else if (northFirst) {
                dist = (c - a) + (d - b);
            }
            sb.append(dist).append("\n");
        }
        System.out.print(sb);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        String S = br.readLine().trim(); // N chars, for each row
        String T = br.readLine().trim(); // M chars, for each column

        StringBuilder sb = new StringBuilder();

        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int r1 = Integer.parseInt(st.nextToken()) - 1;
            int c1 = Integer.parseInt(st.nextToken()) - 1;
            int r2 = Integer.parseInt(st.nextToken()) - 1;
            int c2 = Integer.parseInt(st.nextToken()) - 1;

            // BFS from (r1, c1) to (r2, c2)
            int[][] dist = new int[N][M];
            for (int[] row : dist) Arrays.fill(row, -1);
            dist[r1][c1] = 0;
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{r1, c1});

            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                int r = cur[0], c = cur[1];
                int d = dist[r][c];

                // Move along east-west road i=r
                if (S.charAt(r) == 'E' && c + 1 < M && dist[r][c+1] == -1) {
                    dist[r][c+1] = d + 1;
                    queue.add(new int[]{r, c+1});
                }
                if (S.charAt(r) == 'W' && c - 1 >= 0 && dist[r][c-1] == -1) {
                    dist[r][c-1] = d + 1;
                    queue.add(new int[]{r, c-1});
                }
                // Move along north-south road j=c
                if (T.charAt(c) == 'S' && r + 1 < N && dist[r+1][c] == -1) {
                    dist[r+1][c] = d + 1;
                    queue.add(new int[]{r+1, c});
                }
                if (T.charAt(c) == 'N' && r - 1 >= 0 && dist[r-1][c] == -1) {
                    dist[r-1][c] = d + 1;
                    queue.add(new int[]{r-1, c});
                }
            }

            sb.append(dist[r2][c2]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static final long INF = (long) 4e18;

    // nearest index >= x with value 1
    static int ge(int[] arr, int x) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] >= x) r = m;
            else l = m + 1;
        }
        return l == arr.length ? -1 : arr[l];
    }

    // nearest index <= x with value 1
    static int le(int[] arr, int x) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= x) l = m + 1;
            else r = m;
        }
        return l == 0 ? -1 : arr[l - 1];
    }

    static long abs(long x) {
        return x >= 0 ? x : -x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int Q = fs.nextInt();

        String S = fs.next(); // horizontal roads directions by row
        String T = fs.next(); // vertical roads directions by column

        // Assume:
        // S[i] = 'E' or 'W'
        // T[j] = 'N' or 'S'
        //
        // Intersection: (x, y) where x is row index [1..N], y is column index [1..M]
        // From (x,y), horizontal move allowed along row x according to S[x]:
        //   E: (x,y)->(x,y+1)
        //   W: (x,y)->(x,y-1)
        // Vertical move allowed along column y according to T[y]:
        //   N: (x,y)->(x-1,y)
        //   S: (x,y)->(x+1,y)
        //
        // Distance is Manhattan length if feasible.
        //
        // A path with at most one turn always suffices if reachable:
        // horizontal then vertical, or vertical then horizontal.
        // For H->V via (x1, c):
        //   row x1 must allow x1,y1 -> x1,c
        //   column c must allow x1,c -> x2,c
        // For V->H via (r, y1):
        //   column y1 must allow x1,y1 -> r,y1
        //   row r must allow r,y1 -> r,y2
        //
        // Each condition becomes membership in one of four sets:
        // rows E, rows W, cols N, cols S.
        // Need existence of c or r in an interval intersecting a set.

        ArrayList<Integer> rowsEList = new ArrayList<>();
        ArrayList<Integer> rowsWList = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            char ch = S.charAt(i);
            if (ch == 'E') rowsEList.add(i + 1);
            else rowsWList.add(i + 1);
        }

        ArrayList<Integer> colsNList = new ArrayList<>();
        ArrayList<Integer> colsSList = new ArrayList<>();
        for (int j = 0; j < M; j++) {
            char ch = T.charAt(j);
            if (ch == 'N') colsNList.add(j + 1);
            else colsSList.add(j + 1);
        }

        int[] rowsE = rowsEList.stream().mapToInt(Integer::intValue).toArray();
        int[] rowsW = rowsWList.stream().mapToInt(Integer::intValue).toArray();
        int[] colsN = colsNList.stream().mapToInt(Integer::intValue).toArray();
        int[] colsS = colsSList.stream().mapToInt(Integer::intValue).toArray();

        StringBuilder out = new StringBuilder();

        while (Q-- > 0) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();

            long ans = INF;

            // Direct same row
            if (x1 == x2) {
                if (y1 <= y2 && S.charAt(x1 - 1) == 'E') ans = Math.min(ans, y2 - y1);
                if (y1 >= y2 && S.charAt(x1 - 1) == 'W') ans = Math.min(ans, y1 - y2);
            }

            // Direct same column
            if (y1 == y2) {
                if (x1 >= x2 && T.charAt(y1 - 1) == 'N') ans = Math.min(ans, x1 - x2);
                if (x1 <= x2 && T.charAt(y1 - 1) == 'S') ans = Math.min(ans, x2 - x1);
            }

            // Horizontal then Vertical
            // Need c in [L..R] such that:
            // row x1 can move from y1 to c
            // column c can move from x1 to x2
            int L = 1, R = M;

            if (S.charAt(x1 - 1) == 'E') L = Math.max(L, y1);
            else R = Math.min(R, y1);

            if (x1 > x2) {
                // need N column
                if (L <= R) {
                    int c = ge(colsN, L);
                    if (c != -1 && c <= R) {
                        ans = Math.min(ans, abs(y1 - c) + abs(x1 - x2));
                    }
                }
            } else if (x1 < x2) {
                // need S column
                if (L <= R) {
                    int c = ge(colsS, L);
                    if (c != -1 && c <= R) {
                        ans = Math.min(ans, abs(y1 - c) + abs(x1 - x2));
                    }
                }
            } else {
                // same row already handled directly; but turning is unnecessary and never shorter
            }

            // Vertical then Horizontal
            // Need r in [U..D] such that:
            // column y1 can move from x1 to r
            // row r can move from y1 to y2
            int U = 1, D = N;

            if (T.charAt(y1 - 1) == 'N') D = Math.min(D, x1);
            else U = Math.max(U, x1);

            if (y1 < y2) {
                // need E row
                if (U <= D) {
                    int r = ge(rowsE, U);
                    if (r != -1 && r <= D) {
                        ans = Math.min(ans, abs(x1 - r) + abs(y1 - y2));
                    }
                }
            } else if (y1 > y2) {
                // need W row
                if (U <= D) {
                    int r = ge(rowsW, U);
                    if (r != -1 && r <= D) {
                        ans = Math.min(ans, abs(x1 - r) + abs(y1 - y2));
                    }
                }
            } else {
                // same column already handled directly
            }

            out.append(ans == INF ? -1 : ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    input = sys.stdin.readline

    N, M = map(int, input().split())
    S = input().strip()   # horizontal roads: row i direction
    T = input().strip()   # vertical roads: column j direction
    Q = int(input())

    # rows
    east_rows = [i for i, c in enumerate(S) if c == 'E']
    west_rows = [i for i, c in enumerate(S) if c == 'W']
    # cols
    south_cols = [j for j, c in enumerate(T) if c == 'S']
    north_cols = [j for j, c in enumerate(T) if c == 'N']

    INF = 10**30

    if east_rows:
        min_e = east_rows[0]
        max_e = east_rows[-1]
    else:
        min_e = INF
        max_e = -INF

    if west_rows:
        min_w = west_rows[0]
        max_w = west_rows[-1]
    else:
        min_w = INF
        max_w = -INF

    if south_cols:
        min_s = south_cols[0]
        max_s = south_cols[-1]
    else:
        min_s = INF
        max_s = -INF

    if north_cols:
        min_n = north_cols[0]
        max_n = north_cols[-1]
    else:
        min_n = INF
        max_n = -INF

    out = []

    for _ in range(Q):
        a, b, c, d = map(int, input().split())
        a -= 1
        b -= 1
        c -= 1
        d -= 1

        ans = INF

        # 1-segment paths
        if a == c:
            if b <= d and S[a] == 'E':
                ans = min(ans, d - b)
            if b >= d and S[a] == 'W':
                ans = min(ans, b - d)

        if b == d:
            if a <= c and T[b] == 'S':
                ans = min(ans, c - a)
            if a >= c and T[b] == 'N':
                ans = min(ans, a - c)

        # 2-segment paths: horizontal then vertical
        # Need row a can go from b to d, and column d can go from a to c
        if ((b <= d and S[a] == 'E') or (b >= d and S[a] == 'W')):
            if ((a <= c and T[d] == 'S') or (a >= c and T[d] == 'N')):
                ans = min(ans, abs(d - b) + abs(c - a))

        # 2-segment paths: vertical then horizontal
        # Need column b can go from a to c, and row c can go from b to d
        if ((a <= c and T[b] == 'S') or (a >= c and T[b] == 'N')):
            if ((b <= d and S[c] == 'E') or (b >= d and S[c] == 'W')):
                ans = min(ans, abs(c - a) + abs(d - b))

        # 3-segment paths:
        # row a -> some column y -> some row x -> column d -> destination
        #
        # Since cost is |y-b| + |x-a| + |d-y| + |c-x|,
        # minimizing over y and x independently gives:
        #   min_y (|y-b| + |d-y|) + min_x (|x-a| + |c-x|)
        # with constraints:
        #   row a reaches y
        #   column y reaches x
        #   row x reaches d
        #   column d reaches c
        #
        # The feasible y-set depends only on direction of row a and column y.
        # The feasible x-set depends only on direction of column d and row x.
        #
        # This reduces to checking four combinations of column-direction / row-direction.

        # For y:
        # row a to y:
        #   if S[a]=='E' => y >= b
        #   if S[a]=='W' => y <= b
        # and column y to x:
        #   if T[y]=='S' => x >= a
        #   if T[y]=='N' => x <= a
        #
        # For x:
        # row x to d:
        #   if row is E => d >= current col on row x, but current col is y
        #   handled by y-part only through total formula, so instead use row type
        # column d to c:
        #   if T[d]=='S' => c >= x
        #   if T[d]=='N' => c <= x
        #
        # More directly, a valid 3-segment route exists iff there is some intermediate row x
        # that can be reached from column y and can reach column d, and some y reachable from row a
        # and reaching row x. This is equivalent to choosing:
        #   y among columns of a certain direction in a half-line from b
        #   x among rows of a certain direction in a half-line from c
        # and cost separates.

        # We enumerate the direction of the middle vertical road (at y)
        # and the middle horizontal road (at x).

        # Helper for min over columns y of a given type in a half-line:
        # value = |y-b| + |d-y|
        # If there exists such y in [L, R], minimum is:
        #   d-b if interval [b,d] intersects feasible set
        #   otherwise distance to nearest feasible y from segment [min(b,d), max(b,d)] plus (d-b abs)
        segL = min(b, d)
        segR = max(b, d)
        base_col = abs(d - b)

        def col_cost(dir_char):
            if dir_char == 'S':
                if S[a] == 'E':
                    # y >= b, T[y]='S'
                    if not south_cols:
                        return INF
                    if max_s < b:
                        return INF
                    if max(segL, b) <= min(segR, max_s) and min_s <= segR:
                        # need some south col in [max(b,segL), segR]
                        # easier with boundary logic below
                        pass
                    # nearest south col to interval [max(b, -inf), +inf)
                    L = b
                    # If any south col in [max(segL,L), segR], extra 0
                    if min_s <= segR and max_s >= max(segL, L):
                        return base_col
                    # otherwise nearest feasible south col y >= L to [segL,segR]
                    if max_s < max(segL, L):
                        y = max_s
                    else:
                        # min_s > segR
                        y = max(min_s, L)
                    return abs(y - b) + abs(d - y)
                else:
                    # y <= b, T[y]='S'
                    if not south_cols:
                        return INF
                    if min_s > b:
                        return INF
                    R = b
                    if min_s <= min(segR, R) and max_s >= segL:
                        return base_col
                    if min_s > min(segR, R):
                        y = min_s
                    else:
                        y = min(max_s, R)
                    return abs(y - b) + abs(d - y)
            else:  # 'N'
                if S[a] == 'E':
                    if not north_cols:
                        return INF
                    if max_n < b:
                        return INF
                    L = b
                    if min_n <= segR and max_n >= max(segL, L):
                        return base_col
                    if max_n < max(segL, L):
                        y = max_n
                    else:
                        y = max(min_n, L)
                    return abs(y - b) + abs(d - y)
                else:
                    if not north_cols:
                        return INF
                    if min_n > b:
                        return INF
                    R = b
                    if min_n <= min(segR, R) and max_n >= segL:
                        return base_col
                    if min_n > min(segR, R):
                        y = min_n
                    else:
                        y = min(max_n, R)
                    return abs(y - b) + abs(d - y)

        # Helper for min over rows x of given type in half-line determined by T[d] and c:
        # value = |x-a| + |c-x|
        segLr = min(a, c)
        segRr = max(a, c)
        base_row = abs(c - a)

        def row_cost(dir_char):
            # row x has direction dir_char and must be able to go to d
            # plus column d must go from x to c:
            # if T[d]=='S' => x <= c
            # if T[d]=='N' => x >= c
            if T[d] == 'S':
                # x <= c
                if dir_char == 'E':
                    if not east_rows:
                        return INF
                    if min_e > c:
                        return INF
                    R = c
                    if min_e <= min(segRr, R) and max_e >= segLr:
                        return base_row
                    if min_e > min(segRr, R):
                        x = min_e
                    else:
                        x = min(max_e, R)
                    return abs(x - a) + abs(c - x)
                else:
                    if not west_rows:
                        return INF
                    if min_w > c:
                        return INF
                    R = c
                    if min_w <= min(segRr, R) and max_w >= segLr:
                        return base_row
                    if min_w > min(segRr, R):
                        x = min_w
                    else:
                        x = min(max_w, R)
                    return abs(x - a) + abs(c - x)
            else:  # T[d] == 'N', x >= c
                if dir_char == 'E':
                    if not east_rows:
                        return INF
                    if max_e < c:
                        return INF
                    L = c
                    if min_e <= segRr and max_e >= max(segLr, L):
                        return base_row
                    if max_e < max(segLr, L):
                        x = max_e
                    else:
                        x = max(min_e, L)
                    return abs(x - a) + abs(c - x)
                else:
                    if not west_rows:
                        return INF
                    if max_w < c:
                        return INF
                    L = c
                    if min_w <= segRr and max_w >= max(segLr, L):
                        return base_row
                    if max_w < max(segLr, L):
                        x = max_w
                    else:
                        x = max(min_w, L)
                    return abs(x - a) + abs(c - x)

        # Combine 4 combinations
        for mid_col_dir in ('S', 'N'):
            cc = col_cost(mid_col_dir)
            if cc >= INF:
                continue
            for mid_row_dir in ('E', 'W'):
                rc = row_cost(mid_row_dir)
                if rc >= INF:
                    continue
                ans = min(ans, cc + rc)

        out.append(str(ans if ans < INF else -1))

    print("\n".join(out))

if __name__ == "__main__":
    solve()
